problems.reference:
#include <stdio.h>

#define MAXN 1005

typedef struct
{
    int data[MAXN];
    int length;
} SqList;

/* 删除顺序表中所有值等于 x 的元素，保持其余元素的相对顺序 */
void RemoveAll(SqList *L, int x)
{
    int i, k = 0;

    for (i = 0; i < L->length; i++) {
        if (L->data[i] != x) {
            L->data[k] = L->data[i];
            k++;
        }
    }
    L->length = k;
}

int main(void)
{
    SqList L;
    int i, x;

    if (scanf("%d %d", &L.length, &x) != 2)
        return 1;
    for (i = 0; i < L.length; i++)
        scanf("%d", &L.data[i]);

    RemoveAll(&L, x);

    if (L.length == 0)
        printf("NULL\n");
    else {
        for (i = 0; i < L.length; i++) {
            if (i == 0)
                printf("%d", L.data[i]);
            else
                printf(" %d", L.data[i]);
        }
        printf("\n");
    }
    printf("%d\n", L.length);

    return 0;
}
